function Get-AI5RepositorySnapshot {param([string]$Path);if(!(Test-Path (Join-Path $Path '.git'))-and!(Test-Path (Join-Path $Path '.git') -PathType Leaf)){return[ordered]@{repository=$false;path=$Path}};$branch=(& git -C $Path branch --show-current 2>$null);$head=(& git -C $Path rev-parse HEAD 2>$null);$status=@(& git -C $Path status --porcelain=v2 --untracked-files=all 2>$null);[ordered]@{repository=$true;path=[IO.Path]::GetFullPath($Path);branch=$branch;head=$head;dirty=($status.Count-gt 0);status=@($status);captured_at=[DateTime]::UtcNow.ToString('o')}}
function Enter-AI5RepositoryLock {param([string]$RuntimeRoot,[string]$TaskId,[string]$Path);$lock=Join-Path $RuntimeRoot 'repository.lock';$stream=[IO.File]::Open($lock,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$snapshot=Get-AI5RepositorySnapshot $Path;$record=[ordered]@{task_id=$TaskId;pid=$PID;snapshot=$snapshot;created_at=[DateTime]::UtcNow.ToString('o')};$bytes=[Text.Encoding]::UTF8.GetBytes(($record|ConvertTo-Json -Depth 8));$stream.Write($bytes,0,$bytes.Length);return[ordered]@{path=$lock;record=$record}}catch{$stream.Dispose();Remove-Item -LiteralPath $lock -Force -ErrorAction SilentlyContinue;throw}finally{if($stream){$stream.Dispose()}}}
function Exit-AI5RepositoryLock {param($Lock);if($Lock-and$Lock.path){Remove-Item -LiteralPath $Lock.path -Force -ErrorAction SilentlyContinue}}
